import{_ as t,o,c as s,l as a,t as n,N as r}from"./chunks/framework.Bbd9fWQx.js";const b=JSON.parse('{"title":"erofs | x-cmd man (man5) | the Enhanced Read-Only File System","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | erofs - the Enhanced Read-Only File System","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"erofs | x-cmd man (man5) | the Enhanced Read-Only File System"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | erofs - the Enhanced Read-Only File System"}]]},"headers":[],"params":{"isMan":true,"man":"erofs","category":"man5","desc":"the Enhanced Read-Only File System"},"relativePath":"man5/erofs.md","filePath":"man5/erofs.md"}'),d={name:"man5/erofs.md"},i={class:"visually-hidden"},l=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>erofs - the Enhanced Read-Only File System</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>erofs</strong> is a create-once read-only filesystem, with support for compression and a multi-device backing store.</p><p>There are two inode formats:</p><ul><li><p>32-byte compact with 16-bit UID/GID, 32-bit file size, and no file times</p></li><li><p>64-byte extended with 32-bit UID/GID, 64-bit file size, and a modification time (<em>st_mtim</em>).</p></li></ul><h3 id="mount-options" tabindex="-1">Mount options <a class="header-anchor" href="#mount-options" aria-label="Permalink to &quot;Mount options&quot;">​</a></h3><dl><dt><strong>user_xattr</strong> <br> <strong>nouser_xattr</strong></dt><dd>Controls whether <em>user</em> extended attributes are exposed. Defaults to yes.</dd><dt><strong>acl</strong> <br> <strong>noacl</strong></dt><dd>Controls whether POSIX <strong>acl</strong>(5)s are exposed. Defaults to yes.</dd><dt><strong>cache_strategy</strong>=<strong>disabled</strong>|<strong>readahead</strong>|<strong>readaround</strong></dt><dd>Cache allocation for compressed files: never, if reading from start of file, regardless of position. Defaults to <strong>readaround</strong>.</dd><dt><strong>dax</strong> <br> <strong>dax</strong>=<strong>always</strong>|<strong>never</strong></dt><dd>Direct Access control. If <strong>always</strong> and the source device supports DAX, uncompressed non-inlined files will be read directly, without going through the page cache. <strong>dax</strong> is a synonym for <strong>always</strong>. Defaults to unset, which is equivalent to <strong>never</strong>.</dd><dt><strong>device</strong>=** <em>blobdev</em>* *</dt><dd>Add extra device holding some of the data. Must be given as many times and in the same order as <strong>--blobdev</strong> was to <strong>mkfs.erofs</strong>(1).</dd><dt><strong>domain_id</strong>=** <em>did</em>* * <br> <strong>fsid</strong>=** <em>id</em>* *</dt><dd>Control CacheFiles on-demand read support. To be documented.</dd></dl><h2 id="versions" tabindex="-1">VERSIONS <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;VERSIONS&quot;">​</a></h2><p><strong>erofs</strong> images are versioned through the use of feature flags; these are listed in the <strong>-E</strong> section of <strong>mkfs.erofs</strong>(1),</p><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>Linux must be configured with the <strong>CONFIG_EROFS_FS</strong> option to mount EROFS filesystems. There are sub-configuration items that restrict the availability of some of the parameters above.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>mkfs.erofs</strong>(1), <strong>fsck.erofs</strong>(1), <strong>dump.erofs</strong>(1)</p><p><em>Documentation/filesystems/erofs.txt</em> in the Linux source.</p>',15);function m(e,c,g,h,f,u){return o(),s("div",null,[a("h1",i,n(e.$params.man),1),l])}const _=t(d,[["render",m]]);export{b as __pageData,_ as default};
